<?phpset_time_limit(0);$conn = mysqli_connect('localhost','vedhtkjm_easylog','easyDatabase123');if(!$conn) {    echo 'Database connectivity issue '.mysqli_error($conn);    exit;}mysqli_select_db($conn,'vedhtkjm_easy201920') or die('DB selection issue'.mysql_error());if(!empty($_POST)) {    $societyId = $_POST['societyId'];    $ledgerOpeningArray = $_POST['ledgerOpening'];            if(!empty($ledgerOpeningArray)) {        foreach($ledgerOpeningArray as $key=>$ledgerOpening) {            list($temp,$ledgerId,$amount) = explode('@',$ledgerOpening);                        if(!empty($ledgerId)) {                if($amount == '') {                    $amount = 0;                }                                $updateQue = "UPDATE society_ledger_heads SET opening_amount = $amount WHERE id = $ledgerId and society_id = $societyId";                                $update  = mysqli_query($conn,$updateQue);                if(!$update) {                    mysqli_close($conn);                    die('Error in ledger head updation'. mysqli_error($conn));                }            }        }    }        $memberOpeningArray = $_POST['memberOpening'];        if(!empty($memberOpeningArray)) {        foreach($memberOpeningArray as $key=>$memberOpening) {            list($temp,$memberId,$amount) = explode('@',$memberOpening);                        if(!empty($memberId)) {                if($amount == '') {                    $amount = 0;                }                                $updateQue = "UPDATE members SET op_principal = $amount WHERE id = $memberId and society_id = $societyId";                $update  = mysqli_query($conn,$updateQue);                if(!$update) {                    mysqli_close($conn);                    die('Error in member balance updation'. mysqli_error($conn));                }            }                    }    }}mysqli_close($conn);echo 'Opening balances has been set correctly for next year';exit;